import React, { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from 'react-query';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import { 
  MessageSquare, 
  Plus, 
  Search, 
  Filter,
  Clock,
  User,
  Reply,
  Eye,
  ThumbsUp,
  MoreVertical
} from 'lucide-react';
import toast from 'react-hot-toast';

const Forum = () => {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [showCreateThread, setShowCreateThread] = useState(false);
  const [newThread, setNewThread] = useState({
    title: '',
    content: '',
    category: 'General'
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');

  // Fetch forum threads
  const { data: threadsData, isLoading: threadsLoading } = useQuery(
    'forum-threads',
    () => axios.get('/api/forum/threads').then(res => res.data),
    { refetchInterval: 30000 }
  );

  // Create new thread mutation
  const createThreadMutation = useMutation(
    (threadData) => axios.post('/api/forum/threads', threadData),
    {
      onSuccess: () => {
        queryClient.invalidateQueries('forum-threads');
        setShowCreateThread(false);
        setNewThread({ title: '', content: '', category: 'General' });
        toast.success('Thread created successfully!');
      },
      onError: (error) => {
        toast.error(error.response?.data?.message || 'Failed to create thread');
      }
    }
  );

  const threads = threadsData?.threads || [];
  const categories = ['All', 'General', 'React', 'JavaScript', 'CSS', 'Python', 'Java', 'Other'];

  const filteredThreads = threads.filter(thread => {
    const matchesSearch = thread.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         thread.content.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = selectedCategory === 'All' || thread.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  const handleCreateThread = (e) => {
    e.preventDefault();
    if (!newThread.title.trim() || !newThread.content.trim()) {
      toast.error('Please fill in all fields');
      return;
    }
    createThreadMutation.mutate(newThread);
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInHours = Math.floor((now - date) / (1000 * 60 * 60));

    if (diffInHours < 1) return 'Just now';
    if (diffInHours < 24) return `${diffInHours}h ago`;
    const diffInDays = Math.floor(diffInHours / 24);
    if (diffInDays < 7) return `${diffInDays}d ago`;
    return date.toLocaleDateString();
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-900 mb-4">
            Community Forum
          </h1>
          <p className="text-xl text-gray-600 mb-6">
            Connect with fellow learners and share knowledge
          </p>
          <button className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700">
            Start New Thread
          </button>
        </div>

        <div className="bg-white rounded-lg shadow-md overflow-hidden">
          <div className="px-6 py-4 border-b border-gray-200">
            <h2 className="text-xl font-semibold">Recent Discussions</h2>
          </div>

          <div className="divide-y divide-gray-200">
            {threads.map((thread) => (
              <div key={thread.id} className="p-6 hover:bg-gray-50">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <h3 className="text-lg font-medium text-gray-900 mb-2">
                      {thread.title}
                    </h3>
                    <div className="flex items-center text-sm text-gray-500 space-x-4">
                      <span>By {thread.author}</span>
                      <span>•</span>
                      <span>{thread.replies} replies</span>
                      <span>•</span>
                      <span>{thread.lastActivity}</span>
                    </div>
                  </div>
                  <div className="ml-4">
                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                      {thread.category}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Forum;
